#!/bin/bash
# Simulate retroactive pruning of all committed design dirs:
#  A = files that TODAY's exclusion rules would have dropped (legacy debris)
#  B = additional proposed cuts (dup/derived/static artifacts)
set -u
cd /Users/zhupanov/larch3

echo "=== round-1/plan.txt vs composed-plan.md identity ==="
same=0; diff=0; n=0
for d in larch-logs/design/*/; do
  a="$d/composed-plan.md"; b="$d/plan-review/round-1/plan.txt"
  if [ -f "$a" ] && [ -f "$b" ]; then
    n=$((n+1))
    if cmp -s "$a" "$b"; then same=$((same+1)); else diff=$((diff+1)); fi
  fi
done
echo "runs with both: $n; identical: $same; differ: $diff"

classify() {
  # $1 = path relative to run dir; echo A, B, or KEEP
  local rel="$1" base
  base=$(basename "$rel")
  case "$rel" in
    */revise/*|revise/*) echo A; return ;;
  esac
  case "$base" in
    render-plan-*.prompt|*-output.txt.prompt|*-output-*.txt.prompt) echo A; return ;;
    cursor-plan-*-output*.txt|codex-primary-plan-*-output*.txt|claude-plan-*-output*.txt|dyn-*-output.txt) echo A; return ;;
    cursor-plan-*-output*.txt.*|codex-primary-plan-*-output*.txt.*|claude-plan-*-output*.txt.*) echo A; return ;;
    larch-quiet-*-*.log|*.sidecar|*.dirty-tree|*.untracked-baseline|*.done|*.diag|*.events.jsonl) echo A; return ;;
    *-vote-prompt.txt|claude-plan-*.prompt) echo A; return ;;
    *-collector.failure.log|plan-review-collector.stderr|*.output-files.dropped-slots) echo A; return ;;
    timing-report-final.stderr.log|timing-report-final.failure.log) echo A; return ;;
  esac
  case "$base" in
    aggregate-validate.py|findings.md.tmp|composed-plan.redacted.md) echo B; return ;;
    ballot.txt) echo B; return ;;
    findings-in-scope.pre-dedup.md|findings-in-scope.pre-aggregation.md|aggregate-untagged-input.md) echo B; return ;;
    aggregator-prompt.md) echo B; return ;;
    cursor-plan-voter-prompt.txt|codex-plan-voter-prompt.txt|claude-plan-voter-prompt.txt) echo B; return ;;
    scout-plan-manifest.json.raw|scout-plan-manifest.json.raw.prompt) echo B; return ;;
    *-vote-output.txt.meta|*-vote-output.txt.json) echo B; return ;;
  esac
  # round-N plan snapshots for N>=2 (diffable against previous)
  case "$rel" in
    plan-review/round-1/plan.txt) echo KEEP; return ;;
    plan-review/round-*/plan.txt) echo B; return ;;
  esac
  echo KEEP
}

echo
echo "=== Retroactive simulation across ALL committed design dirs ==="
tmpf=$(mktemp)
for d in larch-logs/design/*/; do
  run=${d%/}
  find "$run" -type f | while IFS= read -r f; do
    sz=$(stat -f %z "$f")
    rel=${f#"$run"/}
    cls=$(classify "$rel")
    echo "$cls $sz"
  done
done > "$tmpf"
awk '{s[$1]+=$2; n[$1]++} END {for (k in s) printf "%-5s %9.1f MB  %6d files\n", k, s[k]/1024/1024, n[k]}' "$tmpf"
echo
awk '{t+=$2; tn++; if ($1!="KEEP"){c+=$2; cn++}} END {printf "cuttable: %.1f of %.1f MB (%.0f%%), %d of %d files (%.0f%%)\n", c/1024/1024, t/1024/1024, 100*c/t, cn, tn, 100*cn/tn}' "$tmpf"
rm -f "$tmpf"

#!/bin/bash
# Full-corpus pattern aggregation for ALL committed /implement runs (608 dirs).
set -u
cd /Users/zhupanov/larch3
find larch-logs/implement -type f | while IFS= read -r f; do
  sz=$(stat -f %z "$f")
  rel=${f#larch-logs/implement/*/}
  norm=$(echo "$rel" | sed -E '
    s/round-[0-9]+/round-N/g;
    s/voter[0-9]+/voterN/g;
    s/larch-quiet-[a-z0-9.-]+-[0-9]+\.log/larch-quiet-SCRIPT-PID.log/;
    s/larch-tokens-[0-9a-f]+/larch-tokens-HASH/;
    s/dyn-[a-z0-9-]+-prompt\.md/dyn-ARCH-prompt.md/;
    s/dyn-[a-z0-9-]+-(codex|cursor|claude)-output/dyn-ARCH-\1-output/;
    s/reviewer-dyn-[a-z0-9-]+\.md/reviewer-dyn-ARCH.md/;
    s/cursor-specialist-[a-z0-9-]+-output/cursor-specialist-ARCH-output/;
    s/codex-specialist-[a-z0-9-]+-output/codex-specialist-ARCH-output/;
    s/(claude|codex|cursor)-specialist-[a-z0-9-]+/\1-specialist-ARCH/;
    s/[0-9]{8}-[0-9]{6}/TS/g;
    s/-[0-9]{4,}(\.|$)/-PID\1/g;
  ')
  echo "$sz $norm"
done | awk '{s[$2]+=$1; n[$2]++} END {for (k in s) printf "%9.1f KB n=%-5d avg=%8.1f KB  %s\n", s[k]/1024, n[k], s[k]/1024/n[k], k}' | sort -rn | head -70
echo "=== done ==="

