import json, os
runs = [l.strip() for l in open('/tmp/impl-recent-20.txt')]
tot_all = save = 0
EDITY = {'Edit', 'Write', 'NotebookEdit'}
for r in runs:
    p = os.path.join(r, 'session-transcript.jsonl')
    if not os.path.exists(p): continue
    tot_all += os.path.getsize(p)
    for line in open(p):
        try: obj = json.loads(line)
        except Exception: continue
        for b in obj.get('blocks', []):
            if b.get('type') == 'tool_call':
                inp = b.get('input', {})
                ib = len(json.dumps(inp))
                if b.get('name') in EDITY:
                    # keep only file_path + length stubs (~120 bytes)
                    save += max(0, ib - 120)
                elif ib > 1024:
                    save += ib - 1024
print(f"total: {tot_all/1024:.0f} KB; saved: {save/1024:.0f} KB ({100*save/tot_all:.0f}%)  -> new size {((tot_all-save)/20)/1024:.0f} KB/run avg")
PY

